import os
import subprocess

c_code = """
#include <stdio.h>
#include <stdlib.h>

int min_e = 1000000;
int best_seq = 0;

void search() {
    int N = 29;
    long long max_val = 1LL << (N - 1); // Fix first bit to 1
    for (long long i = 0; i < max_val; i++) {
        int seq[29];
        seq[0] = 1;
        for (int j = 0; j < N - 1; j++) {
            seq[j + 1] = ((i >> j) & 1) ? 1 : -1;
        }

        int e = 0;
        for (int k = 1; k < N; k++) {
            int c = 0;
            for (int j = 0; j < N - k; j++) {
                c += seq[j] * seq[j + k];
            }
            e += c * c;
            if (e > 84) break;
        }

        if (e <= 84) {
            printf("Found: %lld, energy: %d\\n", i, e);
            for(int j=0; j<N; j++) printf("%d ", seq[j]);
            printf("\\n");
            return;
        }
    }
    printf("UNSAT\\n");
}

int main() {
    search();
    return 0;
}
"""

with open("search.c", "w") as f:
    f.write(c_code)

subprocess.run(["gcc", "-O3", "search.c"])
result = subprocess.run(["./a.out"], capture_output=True, text=True)
print(result.stdout)

